function SongLesson({song}:{song:Song}){const {progress,setProgress}=useProgress();const [onlyKorean,setOnlyKorean]=useState(false);
 const study=studies[song.id];
 const complete=Boolean(study);
 const sections=study?addMusicCuriosities(song.id,study.sections):[{title:'Trecho de estudo',lines:song.clips}];
 const koreanCount=sections.reduce((n,section)=>n+section.lines.filter(line=>koreanPattern.test(line.text)).length,0);
 return <Localized>{<><div className="lyrics-filter"><label htmlFor={song.id+'-only-korean'}><Checkbox id={song.id+'-only-korean'} checked={onlyKorean} onCheckedChange={checked=>setOnlyKorean(checked===true)}/>Mostrar só frases com coreano</label><p role="status">{onlyKorean?`${koreanCount} frases com coreano visíveis. Frases que misturam idiomas continuam aparecendo.`:'Todas as frases visíveis. Ative para ocultar as que não têm palavras em coreano.'}</p></div><div className="music-layout"><aside className="player-panel"><span className="eyebrow">ESTUDO COM VOZ SINTETIZADA</span><h2>{song.title}</h2><p><KoreanText text={song.koTitle}/></p><p>{study?study.summary:song.intro}</p><p>Ouça palavras isoladas tocando nelas. O alto-falante lê a frase inteira.</p><p>Abra “Ver explicação” para revelar a tradução e a gramática de cada frase.</p><span className="pill">{study?.badge??(complete?'Letra completa · estudo preparado':'Trecho · estudo preparado')}</span></aside><section className="music-content"><span className="pill">{song.level}</span><h2>{study?study.heading:song.topic}</h2>{complete&&<p className="muted">Tradução contextual em português. As imagens poéticas podem admitir mais de uma leitura.</p>}{sections.map((section,sectionIndex)=><section className="lyric-section" key={sectionIndex} hidden={onlyKorean&&!section.lines.some(line=>koreanPattern.test(line.text))}><h3>{section.title}</h3>{section.lines.map((line,index)=><Line key={index} id={song.id+'-'+sectionIndex+'-'+index} line={line} hidden={onlyKorean&&!koreanPattern.test(line.text)}/>)}</section>)}{onlyKorean&&koreanCount===0&&<p className="empty-state">Não há frases com coreano nesta letra. Desative o filtro para ver todas.</p>}<Vocabulary {...(study?study.vocabulary:snippetVocabulary[song.id])}/><StreamLinks title={song.title} videoId={song.videoId}/>{study?.references}<div className="music-original"><p className="eyebrow">EXEMPLO ORIGINAL PARA PRATICAR</p><strong><KoreanText text={song.example.ko}/></strong><p>{song.example.pt}</p><p><KoreanText text={song.example.explanation}/></p></div><h2>Agora é com você</h2>{song.exercises.map((e,i)=><ExerciseCard key={e.id} exercise={e} index={i} saved={progress.answers[e.id]} onAnswer={(value,correct)=>setProgress(p=>({...p,answers:{...p.answers,[e.id]:{value,correct}}}))}/>)}</section></div></>}</Localized>;
}
 function Line({id,line,hidden=false}:{id:string;line:StudyLine;hidden?:boolean}){
 const [show,setShow]=useState(false);
 const {locale}=useLocale();
 const english=Boolean(line.english)||!koreanPattern.test(line.text);
 const canReveal=locale==='pt'||!english;
 return <Localized>{<article className="lyric-card" hidden={hidden}><div className="lyric-speech"><KoreanText text={line.text} phrase={false} localize={false}/><AudioButton text={line.text}/></div>{canReveal&&<button className="text-button reveal" aria-expanded={show} aria-controls={id+'-explanation'} onClick={()=>setShow(!show)}>{show?'Ocultar explicação':english?'Ver tradução':'Ver explicação'}</button>}{canReveal&&show&&<div className="explanation" id={id+'-explanation'}><strong>Tradução</strong><p>{line.translation}</p>{line.entries&&line.entries.length>0?<><strong>Gramática · palavra a palavra</strong><ul className="word-analysis">{line.entries.map((entry,index)=><li key={index}><p className="term"><em><KoreanText text={entry.term} phrase={false}/></em><span> = <KoreanText text={entry.meaning} phrase={false}/></span></p>{entry.notes&&entry.notes.map((note,noteIndex)=><p className="note" key={noteIndex}><KoreanText text={note} phrase={false}/></p>)}{entry.card&&<CuriosityCard text={entry.card} source={entry.cardSource}/>}</li>)}</ul></>:line.grammar?<><strong>Por dentro da gramática</strong><p><KoreanText text={line.grammar}/></p></>:null}</div>}</article>}</Localized>;
}
export function CuriosityCard({text,source}:{text:string;source?:string}){
 return <Localized>{<div className="post-it"><span className="post-it-label">Card de curiosidade</span><p><KoreanText text={text} phrase={false}/></p>{source&&<a href={source} target="_blank" rel="noreferrer">Consultar referência ↗</a>}</div>}</Localized>;
}
function StreamLinks({title,videoId}:{title:string;videoId:string}){
 const q=encodeURIComponent('BTS '+title);
 return <Localized>{<div className="stream-links"><h3>Ouvir “{title}” nas plataformas</h3><p className="muted">Escolha onde ouvir a música original.</p><div className="stream-buttons"><a href={videoId?'https://www.youtube.com/watch?v='+videoId:'https://www.youtube.com/results?search_query='+q} target="_blank" rel="noreferrer">YouTube ↗</a><a href={'https://open.spotify.com/search/'+q} target="_blank" rel="noreferrer">Spotify ↗</a><a href={'https://music.apple.com/us/search?term='+q} target="_blank" rel="noreferrer">Apple Music ↗</a></div></div>}</Localized>;
}
type Words={verbs:{ko:string;pt:string}[];nouns:{ko:string;pt:string}[]};
function Vocabulary({verbs,nouns}:Words){return <Localized>{<section className="song-vocabulary"><h2>Palavras importantes</h2><p>Os verbos aparecem na forma de dicionário. Os verbos descritivos estão identificados nas definições.</p><div className="word-columns">{[{title:'Verbos',words:verbs},{title:'Substantivos',words:nouns}].map(group=><div key={group.title}><h3>{group.title}</h3>{group.words.length?group.words.map(w=><p key={w.ko}><KoreanText text={w.ko}/><span> — {w.pt}</span></p>):<p>Nenhum neste trecho.</p>}</div>)}</div></section>}</Localized>}
const snippetVocabulary:Record<string,Words>={
'spring-day':{verbs:[{ko:'보다',pt:'ver'},{ko:'싶다',pt:'querer; auxiliar de desejo'}],nouns:[]},
'life-goes-on':{verbs:[{ko:'멈추다',pt:'parar'}],nouns:[{ko:'세상',pt:'mundo'}]},
'boy-with-luv':{verbs:[{ko:'궁금하다',pt:'ter curiosidade; verbo descritivo'}],nouns:[{ko:'것',pt:'coisa; substantivo dependente'}]},
'dna':{verbs:[{ko:'알아보다',pt:'reconhecer'},{ko:'되다',pt:'tornar-se; auxiliar de mudança'}],nouns:[]},
'idol':{verbs:[{ko:'자유롭다',pt:'ser livre; verbo descritivo'}],nouns:[]}};
